`timescale 1ns/1ps
// -----------------------------------------------------------------------------
// tb_riscv_sc - self-checking testbench for the riscv_sc single-cycle RV32I core
// (SiliconGPT [SGPT] protocol)
//
// * 100 MHz clock (always #5). rst_n is held low for 3 cycles and released on
//   a falling edge; pc must be 0 during reset.
// * The core runs program.hex (generated by tools/gen_program.py) until it
//   halts on ECALL. If it does not halt within MAX_CYCLES a FAIL is printed and
//   the final-state checks still run, so the log shows what went wrong.
// * After halting the TB waits 5 more cycles (ECALL must freeze the core),
//   then checks pc, the executed instruction count, every register x1..x31
//   and every data-memory word written by the program.
// * ALL expected values come from tools/rv_iss.py, an independent RV32I
//   instruction-set simulator (via tools/gen_program.py --vlog); they are
//   pasted into task load_expected below and are not derived from the RTL.
// * x0 is sampled every cycle (rising edge) and must be 0; the samples are
//   reported as one CHECK at the end (test=x0_always_zero).
// * Coverage: instruction classes are sampled every executed cycle from the
//   DUT decode signals (hierarchical references into dut / dut.u_dec).
// -----------------------------------------------------------------------------
module tb_riscv_sc;

  localparam integer MAX_CYCLES = 2000;

  reg         clk;
  reg         rst_n;
  wire [31:0] pc;
  wire [31:0] instr;
  wire        halted;

  riscv_sc dut (.clk(clk), .rst_n(rst_n), .pc(pc), .instr(instr), .halted(halted));

  initial clk = 1'b0;
  always #5 clk = ~clk;

  // ------------------------------------------------------------------ bookkeeping
  integer n_chk, n_pass, n_fail, i, wait_cycles;
  integer executed;              // cycles with an instruction in flight (not halted)
  integer x0_samples, x0_bad;
  time    first_x0_bad_time;

  reg  [31:0] exp_x [1:31];
  reg  [31:0] exp_mem [0:63];
  integer     exp_mem_idx [0:63];
  integer     n_mem_exp;
  reg  [31:0] exp_pc;
  integer     exp_cycles;

  // coverage counters
  integer cov_r, cov_ialu, cov_lui, cov_auipc, cov_jal, cov_jalr, cov_ecall;
  integer cov_ld [0:7];          // indexed by funct3 (0 LB, 1 LH, 2 LW, 4 LBU, 5 LHU)
  integer cov_st [0:7];          // indexed by funct3 (0 SB, 1 SH, 2 SW)
  integer cov_bt [0:7];          // branch taken, indexed by funct3
  integer cov_bn [0:7];          // branch not taken, indexed by funct3

  // ------------------------------------------------------------------ expected values
  task load_expected;
    begin
      // BEGIN EXPECTED
      // ---- expected values generated by tools/gen_program.py (ISS: tools/rv_iss.py)
      exp_pc = 32'h00000224;  // address of the ECALL
      exp_cycles = 166;  // instructions executed including the ECALL
      exp_x[1] = 32'h000001f8;
      exp_x[2] = 32'hfffffffb;
      exp_x[3] = 32'h00000003;
      exp_x[4] = 32'hfffffffb;
      exp_x[5] = 32'h000000fb;
      exp_x[6] = 32'h00000003;
      exp_x[7] = 32'hfffffffb;
      exp_x[8] = 32'h0000fffb;
      exp_x[9] = 32'h00005678;
      exp_x[10] = 32'hfffffffb;
      exp_x[11] = 32'hfffb0378;
      exp_x[12] = 32'h00000087;
      exp_x[13] = 32'h00000378;
      exp_x[14] = 32'h00000000;
      exp_x[15] = 32'h00000000;
      exp_x[16] = 32'h0000003f;
      exp_x[17] = 32'h00000037;
      exp_x[18] = 32'h0000000b;
      exp_x[19] = 32'h0000000b;
      exp_x[20] = 32'h00000000;
      exp_x[21] = 32'h0000000c;
      exp_x[22] = 32'h0000001c;
      exp_x[23] = 32'h0000001d;
      exp_x[24] = 32'h000001e4;
      exp_x[25] = 32'h00000080;
      exp_x[26] = 32'h00000200;
      exp_x[27] = 32'h0000002a;
      exp_x[28] = 32'hfffff000;
      exp_x[29] = 32'hfffff218;
      exp_x[30] = 32'hfffff800;
      exp_x[31] = 32'h000007ff;
      exp_mem_idx[0] = 0; exp_mem[0] = 32'h00001010;
      exp_mem_idx[1] = 1; exp_mem[1] = 32'h00000001;
      exp_mem_idx[2] = 2; exp_mem[2] = 32'h00000000;
      exp_mem_idx[3] = 3; exp_mem[3] = 32'hedcba987;
      exp_mem_idx[4] = 4; exp_mem[4] = 32'h000007f3;
      exp_mem_idx[5] = 5; exp_mem[5] = 32'h00000078;
      exp_mem_idx[6] = 6; exp_mem[6] = 32'hc0000000;
      exp_mem_idx[7] = 7; exp_mem[7] = 32'h0fffffff;
      exp_mem_idx[8] = 8; exp_mem[8] = 32'hfffffffd;
      exp_mem_idx[9] = 9; exp_mem[9] = 32'h12345673;
      exp_mem_idx[10] = 10; exp_mem[10] = 32'h00000008;
      exp_mem_idx[11] = 11; exp_mem[11] = 32'hedcba983;
      exp_mem_idx[12] = 12; exp_mem[12] = 32'h91a2b3c0;
      exp_mem_idx[13] = 13; exp_mem[13] = 32'h00000001;
      exp_mem_idx[14] = 14; exp_mem[14] = 32'h00000000;
      exp_mem_idx[15] = 15; exp_mem[15] = 32'hedcba983;
      exp_mem_idx[16] = 16; exp_mem[16] = 32'h18000000;
      exp_mem_idx[17] = 17; exp_mem[17] = 32'hf8000000;
      exp_mem_idx[18] = 18; exp_mem[18] = 32'h1234567b;
      exp_mem_idx[19] = 19; exp_mem[19] = 32'h12345678;
      exp_mem_idx[20] = 20; exp_mem[20] = 32'h00000003;
      exp_mem_idx[21] = 21; exp_mem[21] = 32'h00000000;
      exp_mem_idx[22] = 22; exp_mem[22] = 32'h00000000;
      exp_mem_idx[23] = 23; exp_mem[23] = 32'h00000001;
      exp_mem_idx[24] = 24; exp_mem[24] = 32'h00000000;
      exp_mem_idx[25] = 25; exp_mem[25] = 32'h00000001;
      exp_mem_idx[26] = 31; exp_mem[26] = 32'hfffffffb;
      exp_mem_idx[27] = 32; exp_mem[27] = 32'h12345678;
      exp_mem_idx[28] = 33; exp_mem[28] = 32'hfffb5678;
      exp_mem_idx[29] = 34; exp_mem[29] = 32'h8703fb78;
      exp_mem_idx[30] = 35; exp_mem[30] = 32'hfffb0378;
      exp_mem_idx[31] = 40; exp_mem[31] = 32'h00000037;
      exp_mem_idx[32] = 41; exp_mem[32] = 32'h0000000c;
      exp_mem_idx[33] = 42; exp_mem[33] = 32'h0000003f;
      n_mem_exp = 34;
      // END EXPECTED
    end
  endtask

  // ------------------------------------------------------------------ check helper
  task automatic check(input [8*20-1:0] tname, input [8*10-1:0] cat, input [31:0] expv,
                       input [31:0] actv, input [8*40-1:0] info);
    begin
      if (actv === expv) begin
        n_pass = n_pass + 1;
        $display("[SGPT] CHECK PASS test=%0s cat=%0s time=%0t exp=0x%h act=0x%h :: %0s pc=0x%h halted=%b",
                 tname, cat, $time, expv, actv, info, pc, halted);
      end else begin
        n_fail = n_fail + 1;
        $display("[SGPT] CHECK FAIL test=%0s cat=%0s time=%0t exp=0x%h act=0x%h :: %0s pc=0x%h halted=%b",
                 tname, cat, $time, expv, actv, info, pc, halted);
      end
      n_chk = n_chk + 1;
    end
  endtask

  // ------------------------------------------------------------------ per-cycle sampling
  // Rising edge: the block reads the pre-edge values (the DUT updates pc and the
  // register file with non-blocking assignments), i.e. the instruction that
  // commits at this edge.
  always @(posedge clk) begin
    if (rst_n === 1'b1) begin
      x0_samples = x0_samples + 1;
      if (dut.u_rf.regs[0] !== 32'd0) begin
        if (x0_bad == 0) first_x0_bad_time = $time;
        x0_bad = x0_bad + 1;
      end
      if (halted === 1'b0) begin
        executed = executed + 1;
        if (dut.u_dec.is_rtype)  cov_r     = cov_r + 1;
        if (dut.u_dec.is_ialu)   cov_ialu  = cov_ialu + 1;
        if (dut.u_dec.is_lui)    cov_lui   = cov_lui + 1;
        if (dut.u_dec.is_auipc)  cov_auipc = cov_auipc + 1;
        if (dut.u_dec.is_jal)    cov_jal   = cov_jal + 1;
        if (dut.u_dec.is_jalr)   cov_jalr  = cov_jalr + 1;
        if (dut.u_dec.is_ecall)  cov_ecall = cov_ecall + 1;
        if (dut.u_dec.is_load)   cov_ld[dut.funct3] = cov_ld[dut.funct3] + 1;
        if (dut.u_dec.is_store)  cov_st[dut.funct3] = cov_st[dut.funct3] + 1;
        if (dut.u_dec.is_branch) begin
          if (dut.br_take) cov_bt[dut.funct3] = cov_bt[dut.funct3] + 1;
          else             cov_bn[dut.funct3] = cov_bn[dut.funct3] + 1;
        end
      end
    end
  end

  // ------------------------------------------------------------------ coverage report
  task automatic cover_line(input [8*16-1:0] bin, input integer hits, input [8*8-1:0] grp);
    $display("[SGPT] COVER bin=%0s hits=%0d group=%0s", bin, hits, grp);
  endtask

  task report_coverage;
    begin
      cover_line("R", cov_r, "class");
      cover_line("I_ALU", cov_ialu, "class");
      cover_line("LUI", cov_lui, "class");
      cover_line("AUIPC", cov_auipc, "class");
      cover_line("JAL", cov_jal, "jump");
      cover_line("JALR", cov_jalr, "jump");
      cover_line("ECALL", cov_ecall, "system");
      cover_line("LB", cov_ld[0], "load");
      cover_line("LH", cov_ld[1], "load");
      cover_line("LW", cov_ld[2], "load");
      cover_line("LBU", cov_ld[4], "load");
      cover_line("LHU", cov_ld[5], "load");
      cover_line("SB", cov_st[0], "store");
      cover_line("SH", cov_st[1], "store");
      cover_line("SW", cov_st[2], "store");
      cover_line("BEQ_taken", cov_bt[0], "branch");
      cover_line("BEQ_not_taken", cov_bn[0], "branch");
      cover_line("BNE_taken", cov_bt[1], "branch");
      cover_line("BNE_not_taken", cov_bn[1], "branch");
      cover_line("BLT_taken", cov_bt[4], "branch");
      cover_line("BLT_not_taken", cov_bn[4], "branch");
      cover_line("BGE_taken", cov_bt[5], "branch");
      cover_line("BGE_not_taken", cov_bn[5], "branch");
      cover_line("BLTU_taken", cov_bt[6], "branch");
      cover_line("BLTU_not_taken", cov_bn[6], "branch");
      cover_line("BGEU_taken", cov_bt[7], "branch");
      cover_line("BGEU_not_taken", cov_bn[7], "branch");
    end
  endtask

  // ------------------------------------------------------------------ main sequence
  reg [8*20-1:0] tn;
  reg [8*40-1:0] txt;

  initial begin
    n_chk = 0; n_pass = 0; n_fail = 0; executed = 0;
    x0_samples = 0; x0_bad = 0; first_x0_bad_time = 0;
    cov_r = 0; cov_ialu = 0; cov_lui = 0; cov_auipc = 0; cov_jal = 0; cov_jalr = 0;
    cov_ecall = 0;
    for (i = 0; i < 8; i = i + 1) begin
      cov_ld[i] = 0; cov_st[i] = 0; cov_bt[i] = 0; cov_bn[i] = 0;
    end
    n_mem_exp = 0; exp_pc = 32'd0; exp_cycles = 0;
    load_expected;
    $display("[SGPT] INFO riscv_sc: program.hex, expected values from tools/rv_iss.py");

    // reset: 3 cycles, released on a falling edge
    rst_n = 1'b0;
    repeat (3) @(negedge clk);
    check("reset_pc", "reset", 32'd0, pc, "rst_n=0 for 3 cycles");
    check("reset_halted", "reset", 32'd0, {31'd0, halted}, "rst_n=0 for 3 cycles");
    rst_n = 1'b1;

    // run until ECALL halts the core
    wait_cycles = 0;
    while (halted !== 1'b1 && wait_cycles < MAX_CYCLES) begin
      @(posedge clk);
      wait_cycles = wait_cycles + 1;
    end
    check("halt_on_ecall", "protocol", 32'd1, {31'd0, halted}, "core must halt on ECALL");
    check("halt_instr", "directed", 32'h0000_0073, instr, "instruction at the halt pc is ECALL");

    // ECALL must freeze the core: let 5 more cycles pass before checking state
    repeat (5) @(negedge clk);
    check("halt_pc", "directed", exp_pc, pc, "pc frozen at the ECALL");
    check("instr_count", "directed", exp_cycles, executed, "instructions executed incl. ECALL");

    for (i = 1; i < 32; i = i + 1) begin
      $sformat(tn, "reg_x%0d", i);
      $sformat(txt, "reg=x%0d src=rv_iss", i);
      check(tn, "directed", exp_x[i], dut.u_rf.regs[i], txt);
    end
    for (i = 0; i < n_mem_exp; i = i + 1) begin
      $sformat(tn, "mem_w%0d", exp_mem_idx[i]);
      $sformat(txt, "word=%0d addr=0x%h src=rv_iss", exp_mem_idx[i], exp_mem_idx[i] * 4);
      check(tn, "directed", exp_mem[i], dut.u_dmem.mem[exp_mem_idx[i]], txt);
    end
    $sformat(txt, "samples=%0d bad=%0d first_bad_t=%0t", x0_samples, x0_bad, first_x0_bad_time);
    check("x0_always_zero", "corner", 32'd0, x0_bad, txt);

    report_coverage;
    $display("[SGPT] SUMMARY total=%0d pass=%0d fail=%0d", n_chk, n_pass, n_fail);
    $display("[SGPT] DONE");
    $finish;
  end

  // ------------------------------------------------------------------ watchdog
  initial begin
    #100000;
    $display("[SGPT] CHECK FAIL test=watchdog cat=protocol time=%0t exp=0x1 act=0x0 :: simulation did not finish within 100 us", $time);
    $display("[SGPT] SUMMARY total=%0d pass=%0d fail=%0d", n_chk + 1, n_pass, n_fail + 1);
    $display("[SGPT] DONE");
    $finish;
  end

endmodule
